import os, collections, datetime
from pathlib import Path

SKIP = {"project-triage", "node_modules", "__pycache__", ".git", ".venv", "venv", ".idea", ".vscode"}
root = Path.home() / "DEV"

per_date_projects = collections.defaultdict(set)
per_date_files = collections.Counter()
total_projects = 0

for e in sorted(root.iterdir()):
    if not e.is_dir() or e.name in SKIP or e.name.startswith("."):
        continue
    total_projects += 1
    for r, dirs, files in os.walk(e):
        dirs[:] = [d for d in dirs if d not in SKIP]
        for f in files:
            try:
                m = (Path(r) / f).stat().st_mtime
            except OSError:
                continue
            d = datetime.date.fromtimestamp(m).isoformat()
            per_date_projects[d].add(e.name)
            per_date_files[d] += 1

print(f"total projects scanned: {total_projects}")
print(f"{'date':<12}{'projects':>9}{'files':>9}")
for d, ps in sorted(per_date_projects.items(), key=lambda kv: -len(kv[1]))[:12]:
    print(f"{d:<12}{len(ps):>9}{per_date_files[d]:>9}")

