import os, datetime, collections
from pathlib import Path

SKIP = {"project-triage", "node_modules", "__pycache__", ".git", ".venv", "venv", ".idea", ".vscode"}
root = Path.home() / "DEV"
TARGETS = {"2026-08-09", "2026-08-05"}

hits = collections.defaultdict(list)
for e in sorted(root.iterdir()):
    if not e.is_dir() or e.name in SKIP or e.name.startswith("."):
        continue
    for r, dirs, files in os.walk(e):
        dirs[:] = [d for d in dirs if d not in SKIP]
        for f in files:
            p = Path(r) / f
            try:
                d = datetime.date.fromtimestamp(p.stat().st_mtime).isoformat()
            except OSError:
                continue
            if d in TARGETS:
                hits[d].append(p.relative_to(root))

for d in sorted(TARGETS):
    lst = hits[d]
    print(f"\n=== {d}: {len(lst)} files ===")
    names = collections.Counter(p.name for p in lst)
    print("top filenames:")
    for n, c in names.most_common(8):
        print(f"   {c:>5}  {n}")
    print("sample paths:")
    for p in lst[:6]:
        print(f"   {p}")

