    render();
  });
  return s;
}

// text editing — the thing the first prototype did not show
function panel(rec, from){
  const p = document.createElement("div");
  p.className = "panel";
  p.addEventListener("mousedown", e => e.stopPropagation());
  p.addEventListener("click", e => e.stopPropagation());

  const needs = from === "inbox" && (!rec.purpose || !rec.next_action);
  if(needs){
    const w = document.createElement("div");
    w.className = "warn";
    w.textContent = "Promotion blocked: purpose and next action are both required.";
    p.append(w);
  }

  const field = (key, label, tag) => {
    const l = document.createElement("label"); l.textContent = label;
    const el = document.createElement(tag);
    if(tag === "textarea") el.rows = 3;
    el.value = rec[key] || "";
    if(!rec[key]) el.classList.add("missing");
    el.placeholder = "—";
    el.addEventListener("input", () => {
      rec[key] = el.value;
      el.classList.toggle("missing", !el.value);
    });
    el.addEventListener("change", () => { note(`${rec.name} ${key} edited`); render(); });
    p.append(l, el);
  };
  field("purpose", "purpose", "textarea");
  field("next_action", "next action", "input");

  const l = document.createElement("label"); l.textContent = "add update";
  const add = document.createElement("input");
  add.placeholder = "one line, then Enter";
  add.addEventListener("keydown", e => {
    if(e.key !== "Enter" || !add.value.trim()) return;
    rec.updates = rec.updates || [];
    rec.updates.unshift({date: DATA.today, note: add.value.trim()});
    note(`${rec.name} update added`);
    render();
  });
  p.append(l, add);

  if(rec.updates && rec.updates.length){
    const box = document.createElement("div"); box.className = "ups";
    rec.updates.slice(0, 6).forEach(u => {
      const d = document.createElement("div"); d.className = "up";
      d.innerHTML = `<b>${u.date}</b> `;
      d.append(document.createTextNode(u.note));
      box.append(d);
    });
    p.append(box);
  }
  return p;
}

