function card(rec, from){
  const open = openCard === rec.name;
  const d = document.createElement("div");
  d.className = "card" + (open ? " open" : "");
  d.dataset.name = rec.name;
  const h = document.createElement("h3");
  h.textContent = rec.name;
  d.append(h, chip(rec));

  if(!open){
    const p = document.createElement("p");
    p.textContent = rec.purpose || "— no purpose yet —";
    d.append(p);
  }
  if(from !== "inbox"){
    const b = document.createElement("div"); b.className="bar";
    const i = document.createElement("i");
    i.style.width = ((stageIdx(rec.stage)+1)/STAGES.length*100).toFixed(0)+"%";
    b.append(i); d.append(b);
    const r = document.createElement("div"); r.className="rk";
    r.textContent = `#${rec.rank ?? "—"} · ${rec.stage||"unstaged"}`;
    d.append(r);
  }
  if(open) d.append(panel(rec, from));

  d.addEventListener("click", () => {
    openCard = open ? null : rec.name;
    render();
  });

  cardDrag(d, rec, from);
  if(open) d.draggable = false;   // let text be selected while editing
  return d;
}

